/**
 * Create a new object from a registered template.
 *
 * @param {string} templateName
 *        Name of the template to clone
 *        (e.g. "LOG_EVENT", "DEVICE", "ACTIVE_NOTIF")
 *
 * @returns {Object|null}
 *        A deep copy of the requested template, or null on error.
 */
function g_newObject(templateName) {

    if (!templateName) {
        node.error("g_newObject(): No template name supplied.");
        return null;
    }

    const templates = global.get("TEMPLATES");

    if (!templates) {
        node.error("g_newObject(): Template registry has not been initialized.");
        return null;
    }

    if (!Object.prototype.hasOwnProperty.call(templates, templateName)) {
        node.error(`g_newObject(): Unknown template '${templateName}'.`);
        return null;
    }

    // Deep copy the template so the caller owns its own object.
    return JSON.parse(JSON.stringify(templates[templateName]));

}

