    if (notifications.activeNotifications[key]) {

        // Ignore duplicate notification.
        return null;

    }

    const activeNotification =
        g_newObject("ACTIVE_NOTIF");

    activeNotification.notificationId =
        msg.payload.notificationId;

    activeNotification.sourceId =
        msg.payload.sourceId;

    activeNotification.startedAt =
        Date.now();

    notifications.activeNotifications[key] =
        activeNotification;

    global.set("notifications", notifications);

}
catch (err) {

    node.error(err);

}

return null;

// -----------------------------------------------------------------------------
// Initialize Heartbeat Service
//
// Executed once during Node-RED startup.
//
// Creates the Heartbeat runtime registry.
//
// -----------------------------------------------------------------------------

const heartbeatObj = {};

global.set("heartbeatObj", heartbeatObj);

return msg;

// -----------------------------------------------------------------------------
// HB Register Device
//
// Creates or updates the heartbeat monitoring entry for a device.
//
// -----------------------------------------------------------------------------

const reg = msg.payload;

const heartbeatObj = global.get("heartbeatObj") || {};
const g_newObject = global.get("g_newObject");

const hb = heartbeatObj[reg.sourceId];

if (!hb) {

    //
    // First registration.
    //
    const hbEntity = g_newObject("HEARTBEAT_ENTITY");

    hbEntity.interval = reg.heartbeatInterval;
    hbEntity.timeout = reg.timeout;

    heartbeatObj[reg.sourceId] = hbEntity;

    global.set("heartbeatObj", heartbeatObj);

    node.log(`Heartbeat monitoring started for '${reg.sourceId}'.`);

    return msg;
}

//
// Already registered.
//
if (
    hb.interval === reg.heartbeatInterval &&
    hb.timeout === reg.timeout
) {

    // Duplicate registration.
    return msg;
}

//
// Registration changed.
// Update monitoring policy.
//
hb.interval = reg.heartbeatInterval;
hb.timeout = reg.timeout;

global.set("heartbeatObj", heartbeatObj);

node.log(`Heartbeat policy updated for '${reg.sourceId}'.`);

return msg;

const heartbeatObj = global.get("heartbeatObj");

const hb = heartbeatObj[msg.payload.sourceId];

if (!hb) {
    node.warn(`Heartbeat received from unregistered source '${msg.payload.sourceId}'.`);
    return null;
}

hb.received++;
hb.lastReceived = Date.now();

global.set("heartbeatObj", heartbeatObj);

return msg;

// -----------------------------------------------------------------------------
// Timer Tick
//
// Evaluates whether each monitored entity is meeting its heartbeat commitment.
//
// -----------------------------------------------------------------------------

const heartbeatObj = global.get("heartbeatObj") || {};

const now = Date.now();

let okCount = 0;
let timeoutCount = 0;

for (const sourceId in heartbeatObj) {

    const hb = heartbeatObj[sourceId];

    const elapsed = now - hb.lastReceived;

    if (elapsed <= hb.timeout) {

        okCount++;

    }
    else {

        timeoutCount++;

    }

}

// -----------------------------------------------------------------------------
// Update node status.
// -----------------------------------------------------------------------------

let fill;
let text;

if (timeoutCount === 0) {

    fill = "green";
    text = `${okCount} OK`;

}
else {

    fill = "yellow";
    text = `${okCount} OK, ${timeoutCount} timeout`;

}

node.status({
    fill: fill,
    shape: "dot",
    text: text
});

return msg;
